//
//   x[j]   = 1 + j / n
//   A[i,j] = ((i + j) % n) / (5 * m)
//
// Optimizations:
//   - Precompute 1/n and 1/(5*m) once to avoid a division inside each element.
//   - Use Noarr traversers for all data-parallel loops.
void init_array(auto A, auto x) {
