		tmp[si] = tmp_i;

		// Second pass over j:
		//   y[j] = y[j] + A[i][j] * tmp[i];
		inner.for_each([&](auto state) {
			y[state] += A[state] * tmp_i;
		});
	});
	#pragma endscop
