using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: m x n, row-major (i = row, j = column)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(x_layout, j_vec);
	// y: length n (dimension 'j')
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
	// tmp: length m (dimension 'i')
	DEFINE_PROTO_STRUCT(tmp_layout, i_vec);
} tuning;

// Array initialization
void init_array(auto A, auto x) {
	using namespace noarr;

	// x: j dimension of length N
	auto n_len = x | get_length<'j'>();
	const num_t fn = static_cast<num_t>(n_len);

	// x[j] = 1 + (j / fn)
	traverser(x).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		x[state] = static_cast<num_t>(1) + static_cast<num_t>(j) / fn;
	});

	// A: dimensions i (M) and j (N)
	auto m_len   = A | get_length<'i'>();
	auto n_len_A = A | get_length<'j'>();

	// Common denominator: 5 * m  (kept as division to preserve original FP semantics)
	const num_t denom = static_cast<num_t>(5) * static_cast<num_t>(m_len);

	// A[i][j] = ((i + j) % n) / (5 * m)
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		num_t numerator = static_cast<num_t>((i + j) % n_len_A);
		A[state] = numerator / denom;
	});
}

// Main computational kernel
//
// Original algorithm (PolyBench ATAX):
//   // y = A^T * (A * x)
//   for i in [0, M):
//     tmp[i] = 0;
//     for j in [0, N):
//       tmp[i] += A[i][j] * x[j];
//   for j in [0, N):
//     y[j] = 0;
//   for i in [0, M):
//     for j in [0, N):
//       y[j] += A[i][j] * tmp[i];
//
// This implementation uses Noarr traversers and optimizes the inner loops:
// - We use a *scalar* accumulator tmp_i for each row i instead of updating
//   tmp[i] in memory on every j iteration. This removes O(M*N) loads/stores
//   of tmp[i] and keeps the accumulation in a register.
// - After finishing the first pass over j, we write tmp[i] once.
// - In the second pass over j we reuse the scalar tmp_i directly instead of
//   reading tmp[i] from memory N times.
// - Access to A and x remains j-contiguous (row-major) for good cache and
//   vectorization behavior.
[[gnu::flatten, gnu::noinline]]
void kernel_atax(auto A, auto x, auto y, auto tmp) {
	using namespace noarr;

	#pragma scop
	// y[j] = 0 for all j
	traverser(y).for_each([&](auto sy) {
		y[sy] = static_cast<num_t>(0);
	});

	// for (i = 0; i < M; i++) { ... }
	// We traverse all four bags together so they share the same (i,j) state.
	traverser(A, x, y, tmp).template for_dims<'i'>([&](auto inner) {
		// state with fixed i (only 'i' index present)
		auto si = inner.state();

		// Local accumulator for tmp[i], stays in a register while iterating j.
		num_t tmp_i = static_cast<num_t>(0);

		// First inner loop over j:
		//   tmp[i] = sum_j A[i][j] * x[j]
		// We keep the partial sum in tmp_i and avoid touching tmp[i] in memory.
		inner.for_each([&](auto state) {
			// state has both 'i' and 'j'; A is row-major in 'j'.
			tmp_i += A[state] * x[state]; // x[state] uses only 'j'
		});

		// Store the final value of tmp[i] once, matching original semantics.
		tmp[si] = tmp_i;

		// Second inner loop over j:
		//   y[j] += A[i][j] * tmp[i]
		// We reuse tmp_i instead of loading tmp[i] from memory N times.
		inner.for_each([&](auto state) {
			y[state] += A[state] * tmp_i; // y[state] uses only 'j'
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// common length proto-structure
	auto set_lengths = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout   ^ set_lengths);
	auto x   = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout   ^ set_lengths);
	auto y   = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout   ^ set_lengths);
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), x.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_atax(A.get_ref(), x.get_ref(), y.get_ref(), tmp.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print result vector y
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
